 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, color, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const root = new Group();
  root.name = config.name ?? 'journal-card-1-label';

  const visual = config.intent?.visualSpec ?? {};
  const colors = visual.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const width = 1.6;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial();
  material.colorNode = color(colors.surface);

  const plane = new Mesh(geometry, material);
  plane.name = 'label-plane';
  root.add(plane);

  let loadedTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      tex.colorSpace = ctx.THREE.SRGBColorSpace;

      const gradient = mix(color(colors.ink), color(colors.surface), uv().y);
      const surface = mix(texture(tex, uv()), gradient, 0.42);

      material.colorNode = surface;
      material.needsUpdate = true;
    });
  }

  const textContent = config.textContent ?? visual.textContent ?? [];
  for (const item of textContent) {
    if (!item.text) continue;

    const label = ctx.fontAtlas.createText(String(item.text), {
      fontSize: 0.34,
      color: colors.paper,
      align: 'left',
    });

    label.position.set(-width * 0.42, -0.05, 0.03);
    label.name = `label-text-${item.role ?? 'text'}`;
    root.add(label);
  }

  const primitiveCleanups = [];
  if (config.cinematicPrimitives) {
    for (const p of config.cinematicPrimitives) {
      if (ctx.primitives?.[p.name]) {
        const instance = ctx.primitives[p.name](root, p.params ?? {});
        if (instance?.cleanup) primitiveCleanups.push(instance.cleanup);
      }
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    primitiveCleanups.forEach((c) => {
      try {
        c();
      } catch (e) {}
    });

    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return root;
}
